import {buildDocument,clampPosition,wavBlob} from './core.js';
import {allDocuments,saveDocument,deleteDocument} from './storage.js';
import {extractFile} from './importer.js';
const $=s=>document.querySelector(s);
const demo=buildDocument('Votre première lecture','DÉCOUVERTE',['Bienvenue dans votre espace de lecture. Ici, vous pouvez écouter vos cours et suivre chaque phrase, tranquillement.\n\nUn document de cent trente pages ? Avancez une page à la fois. Faites une pause quand vous en avez besoin, puis reprenez là où vous en étiez.\n\nCommencez par ajouter un document, ou écoutez simplement ce petit texte. Il n’y a aucune course à gagner. Juste votre rythme à trouver.'],'demo');
let docs=[demo],doc=demo,page=1,index=0,playing=false,paused=false,run=0,audio=null,audioUrl=null,worker=null,job=0,utterance=null,importController=null;
const jobs=new Map(),cache=new Map();let storageTimer;
function status(message,error=false){$('#status').textContent=message;$('#status').classList.toggle('error',error);}
function remember(){doc.position=index;clearTimeout(storageTimer);const target=doc;if(target.id!=='demo')storageTimer=setTimeout(()=>saveDocument(target).catch(()=>status('Lecture disponible, mais la sauvegarde locale a échoué : stockage insuffisant ou désactivé.',true)),300);try{localStorage.setItem('lisi-last',doc.id);}catch{}}
function showLibrary(){const list=$('#documents');list.replaceChildren();$('#doc-count').textContent=docs.length;for(const d of docs){const row=document.createElement('div');row.className='doc-row';const button=document.createElement('button');button.className='doc-card'+(d.id===doc.id?' active':'');button.setAttribute('aria-current',d.id===doc.id?'true':'false');const icon=document.createElement('span');icon.className='doc-symbol';icon.textContent=d.id==='demo'?'LISI':d.kind;const content=document.createElement('span');const name=document.createElement('strong');name.textContent=d.name;const info=document.createElement('small');info.textContent=`${d.pages.length} ${d.kind==='DOCX'?'section':'page'}${d.pages.length>1?'s':''} · ${d.id==='demo'?'Découverte':'Sur cet appareil'}`;content.append(name,info);button.append(icon,content);button.onclick=()=>selectDocument(d);row.append(button);if(d.id!=='demo'){const del=document.createElement('button');del.className='delete-doc';del.textContent='×';del.setAttribute('aria-label',`Retirer ${d.name}`);del.onclick=async()=>{if(!confirm(`Retirer « ${d.name} » de cette bibliothèque ? Le fichier original restera sur votre appareil.`))return;try{await deleteDocument(d.id);docs=docs.filter(x=>x.id!==d.id);if(doc.id===d.id)selectDocument(demo);else showLibrary();}catch{status('Impossible de retirer ce document du stockage.',true);}};row.append(del);}list.append(row);}}
function selectDocument(d){stop();cache.clear();doc=d;index=clampPosition(d.position,d.sentences.length);page=d.sentences[index]?.page||1;showLibrary();render();remember();status(d.id==='demo'?'Choisissez un document ou écoutez ce texte de découverte.':'Document prêt. Appuyez sur Écouter pour commencer.');}
function render(){const isDemo=doc.id==='demo';$('#doc-title').textContent=isDemo?'Prenez le temps de lire.':doc.name;$('#doc-type').textContent=isDemo?'POUR COMMENCER':doc.kind+' · VOTRE DOCUMENT';$('#page-meta').textContent=isDemo?'Texte de découverte':doc.kind==='DOCX'?'Sections de lecture · pagination adaptée':'Votre progression est enregistrée';$('#page-input').value=page;$('#page-input').max=doc.pages.length;$('#page-total').textContent=`sur ${doc.pages.length}`;$('#prev-page').disabled=page<=1;$('#next-page').disabled=page>=doc.pages.length;$('#paper-kicker').textContent=isDemo?'BIENVENUE DANS LISI':`${doc.kind==='DOCX'?'SECTION':'PAGE'} ${page}`;$('#page-heading').hidden=!isDemo;$('#paper-number').textContent=String(page).padStart(2,'0');$('#player-title').textContent=isDemo?'Votre première lecture':doc.name;$('#text').replaceChildren();let paragraph=-1,p;let hasText=false;doc.sentences.forEach((sentence,i)=>{if(sentence.page!==page)return;hasText=true;if(sentence.paragraph!==paragraph){p=document.createElement('p');$('#text').append(p);paragraph=sentence.paragraph;}const span=document.createElement('span');span.className='sentence';span.dataset.index=i;span.tabIndex=0;span.setAttribute('role','button');span.setAttribute('aria-label','Lire : '+sentence.text);span.textContent=sentence.text;const jump=()=>{stop();index=i;remember();highlight();void start();};span.onclick=jump;span.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();jump();}};p.append(span,document.createTextNode(' '));});$('#empty-page').hidden=hasText;$('#play').disabled=!doc.sentences.length;$('#position').max=Math.max(0,doc.sentences.length-1);highlight();}
function highlight(){document.querySelectorAll('.sentence.active').forEach(x=>x.classList.remove('active'));const el=document.querySelector(`.sentence[data-index="${index}"]`);el?.classList.add('active');if(playing&&$('#follow').checked&&el){const rect=el.getBoundingClientRect();if(rect.top<110||rect.bottom>innerHeight-180)el.scrollIntoView({behavior:'auto',block:'center'});}$('#position').value=index;$('#progress-label').textContent=doc.sentences.length?`Phrase ${index+1} sur ${doc.sentences.length}`:'Aucun texte';$('#previous').disabled=index<=0;$('#next').disabled=index>=doc.sentences.length-1;}
function showPlay(){const active=playing&&!paused;$('#play-label').textContent=active?'Pause':paused?'Reprendre':'Écouter';$('#play-icon').textContent=active?'Ⅱ':'▶';$('#play').setAttribute('aria-label',active?'Mettre en pause':paused?'Reprendre la lecture':'Commencer la lecture');}
function cleanupAudio(){if(audio){audio.onended=null;audio.onerror=null;audio.pause();audio.src='';audio=null;}if(audioUrl){URL.revokeObjectURL(audioUrl);audioUrl=null;}}
function stop(){run++;playing=false;paused=false;cleanupAudio();if('speechSynthesis'in window)speechSynthesis.cancel();utterance=null;showPlay();}
function getWorker(){if(!worker){worker=new Worker('./voice-worker.js',{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress'){if(playing)status(data.message);return;}const pending=jobs.get(data.id);if(!pending)return;jobs.delete(data.id);if(data.type==='error')pending.reject(new Error(data.message));else pending.resolve(data.samples);};worker.onerror=()=>{for(const j of jobs.values())j.reject(new Error('Le moteur vocal n’a pas pu démarrer. Vérifiez votre connexion et réessayez avec Chrome ou Edge à jour.'));jobs.clear();worker.terminate();worker=null;cache.clear();};}return worker;}
function getAudio(i){const key=doc.id+':'+i;if(cache.has(key))return cache.get(key);const text=doc.sentences[i]?.text;if(!text)return Promise.resolve(null);const promise=new Promise((resolve,reject)=>{const id=++job;jobs.set(id,{resolve,reject});try{getWorker().postMessage({id,text});}catch(error){jobs.delete(id);reject(error);}});cache.set(key,promise);promise.catch(()=>cache.delete(key));for(const k of cache.keys())if(k!==key&&cache.size>4)cache.delete(k);return promise;}
async function start(){if(!doc.sentences.length)return;if(paused){paused=false;playing=true;showPlay();if(audio)try{await audio.play();}catch(error){fail(error);}else if(utterance)speechSynthesis.resume();return;}if(playing)return;playing=true;paused=false;const token=++run;showPlay();await speakCurrent(token);}
function fail(error){stop();if(error.name==='NotAllowedError'){status('Votre navigateur attend un clic : appuyez sur Écouter pour lancer la voix.');return;}status('La lecture n’a pas démarré. '+(error.message||'Réessayez.'),true);}
async function speakCurrent(token){if(token!==run||!playing)return;page=doc.sentences[index].page;render();remember();const advance=()=>{if(token!==run)return;index++;if(index>=doc.sentences.length){stop();index=Math.max(0,doc.sentences.length-1);remember();highlight();status('Lecture terminée. Vous pouvez réécouter une phrase en cliquant dessus.');return;}void speakCurrent(token);};
  if($('#voice').value==='system'){
    if(!('speechSynthesis'in window)){fail(new Error('Aucune voix système disponible dans ce navigateur.'));return;}
    utterance=new SpeechSynthesisUtterance(doc.sentences[index].text);utterance.lang='fr-FR';utterance.rate=Number($('#speed').value);const voices=speechSynthesis.getVoices().filter(v=>v.lang.startsWith('fr'));utterance.voice=voices.find(v=>/natural|neural|online/i.test(v.name))||voices[0]||null;utterance.onend=advance;utterance.onerror=e=>{if(token===run&&e.error!=='interrupted'&&e.error!=='canceled')fail(new Error('La voix de cet appareil est indisponible.'));};if(!paused)speechSynthesis.speak(utterance);status('Lecture avec la voix de cet appareil. La qualité et la confidentialité dépendent du navigateur.');return;
  }
  try{status('Préparation de la voix française…');const samples=await getAudio(index);if(token!==run)return;cleanupAudio();audioUrl=URL.createObjectURL(wavBlob(samples));audio=new Audio(audioUrl);audio.playbackRate=Number($('#speed').value);audio.preservesPitch=true;audio.onended=advance;audio.onerror=()=>{if(token===run)fail(new Error('Impossible de lire le son généré.'));};if(!paused)await audio.play();if(token!==run)return;status(paused?'Lecture en pause.':'Siwis vous accompagne. La phrase entendue est surlignée.');if(index+1<doc.sentences.length)void getAudio(index+1).catch(()=>{});}catch(error){if(token===run)fail(error);}
}
function toggle(){if(playing&&!paused){paused=true;audio?.pause();if(utterance)speechSynthesis.pause();showPlay();status('Lecture en pause. Reprenez quand vous voulez.');}else void start();}
function move(next,autoplay=playing){stop();index=clampPosition(next,doc.sentences.length);page=doc.sentences[index]?.page||1;render();remember();if(autoplay)void start();}
function goPage(next){stop();page=Math.max(1,Math.min(doc.pages.length,Number(next)||1));const i=doc.sentences.findIndex(s=>s.page===page);if(i>=0){index=i;remember();}render();if(i<0)status('Cette page est vide. La lecture reprendra à la dernière phrase sélectionnée.');}
$('#play').onclick=toggle;$('#previous').onclick=()=>move(index-1);$('#next').onclick=()=>move(index+1);$('#position').onchange=e=>move(Number(e.target.value));$('#prev-page').onclick=()=>goPage(page-1);$('#next-page').onclick=()=>goPage(page+1);$('#page-input').onchange=e=>goPage(e.target.value);
$('#focus').onclick=()=>{const on=document.body.classList.toggle('focus-mode');$('#focus').setAttribute('aria-pressed',String(on));$('#focus').textContent=on?'Quitter la concentration':'Mode concentration';};
$('#help').onclick=()=>$('#help-dialog').showModal();document.querySelectorAll('#help-dialog .close,#help-dialog .close-help').forEach(b=>b.onclick=()=>$('#help-dialog').close());
$('#test-voice').onclick=()=>{stop();void start();};
$('#voice').onchange=()=>{stop();$('#voice-hint').textContent=$('#voice').value==='neural'?'Voix neuronale, générée sur votre appareil. Téléchargement au premier lancement.':'Qualité variable selon l’appareil. Certaines voix utilisent un service en ligne.';$('#player-subtitle').textContent=$('#voice').value==='neural'?'Siwis · Français':'Voix de cet appareil';savePreferences();};
function applyPreferences(){const size=Number($('#size').value),spacing=Number($('#spacing').value);document.documentElement.style.setProperty('--reading-size',size+'px');document.documentElement.style.setProperty('--line-height',spacing);document.documentElement.style.setProperty('--reading-font',$('#font').value==='dys'?'OpenDyslexic, Arial, sans-serif':"'Segoe UI', Arial, sans-serif");$('#size-value').textContent=size+' px';$('#spacing-value').textContent=spacing<1.8?'Compact':spacing>2.1?'Très aéré':'Aéré';if(audio)audio.playbackRate=Number($('#speed').value);}
function setTheme(theme){const colors={light:['#fff','#253144','#e4edff'],cream:['#fff5df','#463d2b','#e9d9a9'],night:['#202c3d','#edf2fa','#344e73']};if(!colors[theme])return;const [bg,ink,hl]=colors[theme];document.documentElement.style.setProperty('--paper',bg);document.documentElement.style.setProperty('--ink',ink);document.documentElement.style.setProperty('--highlight',hl);document.querySelectorAll('[data-theme]').forEach(b=>{b.classList.toggle('selected',b.dataset.theme===theme);b.setAttribute('aria-pressed',String(b.dataset.theme===theme));});}
function savePreferences(){try{localStorage.setItem('lisi-preferences',JSON.stringify({size:$('#size').value,spacing:$('#spacing').value,font:$('#font').value,speed:$('#speed').value,follow:$('#follow').checked,theme:document.querySelector('[data-theme].selected').dataset.theme,voice:$('#voice').value}));}catch{}}
for(const id of ['size','spacing','font','speed','follow'])$('#'+id).oninput=()=>{applyPreferences();savePreferences();if(id==='speed'&&utterance&&playing)move(index,true);};
document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{setTheme(b.dataset.theme);savePreferences();});
try{const p=JSON.parse(localStorage.getItem('lisi-preferences')||'null');if(p){for(const id of ['size','spacing','font','speed','voice'])if(p[id])$('#'+id).value=p[id];$('#follow').checked=p.follow!==false;setTheme(p.theme||'light');}}catch{}
applyPreferences();$('#voice').onchange();
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target.tagName)&&!e.target.closest('dialog')&&!e.target.isContentEditable){e.preventDefault();toggle();}});
window.addEventListener('pagehide',()=>{stop();remember();if(doc.id!=='demo')void saveDocument(doc).catch(()=>{});});
$('#import').onclick=()=>$('#file').click();$('#dropzone').onclick=()=>$('#file').click();$('#dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file').click();}};
$('#file').onchange=()=>{const file=$('#file').files[0];if(file)void importFile(file);$('#file').value='';};
const zone=$('#dropzone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag');};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');if(e.dataTransfer.files[0])void importFile(e.dataTransfer.files[0]);};
$('#cancel-import').onclick=()=>{importController?.abort();$('#import-status').textContent='Annulation en cours…';};$('#import-dialog').addEventListener('cancel',e=>{e.preventDefault();$('#cancel-import').click();});
async function importFile(file){if(importController)return;stop();importController=new AbortController();const signal=importController.signal;let imported=false;$('#import-dialog').showModal();$('#import-progress').removeAttribute('value');$('#import-status').textContent='Ouverture du document…';try{const {kind,pages}=await extractFile(file,(message,progress)=>{$('#import-status').textContent=message;if(progress!==undefined)$('#import-progress').value=progress;},signal);if(signal.aborted)throw new DOMException('Annulé','AbortError');const d=buildDocument(file.name.replace(/\.[^.]+$/,''),kind,pages);if(!d.sentences.length)throw new Error('Aucun texte reconnu. Essayez une photo plus nette ou un autre document.');let saved=true;try{await saveDocument(d);}catch{saved=false;}docs.unshift(d);selectDocument(d);imported=saved;status(saved?'Document prêt. La lecture commence…':'Document prêt pour cette session. Le stockage de ce navigateur est indisponible. Appuyez sur Écouter.',!saved);}catch(error){status(signal.aborted?'Import annulé.':error.message||'Impossible de lire ce document.',!signal.aborted);}finally{importController=null;$('#import-dialog').close();if(imported)void start();}}
showLibrary();render();
try{const saved=await allDocuments();docs=[...saved.sort((a,b)=>b.createdAt-a.createdAt),demo];const last=localStorage.getItem('lisi-last');selectDocument(docs.find(d=>d.id===last)||demo);}catch{status('Le stockage local est indisponible. Vos lectures resteront disponibles pendant cette session.',true);}
if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});for(const tool of [{name:'get_reading_state',description:'Lire la progression et la page sélectionnée, sans révéler le contenu du cours.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({page,totalPages:doc.pages.length,sentence:index+1,totalSentences:doc.sentences.length,playing:playing&&!paused})},{name:'go_to_reading_page',description:'Afficher une page et mettre la lecture en pause.',inputSchema:{type:'object',properties:{page:{type:'integer',minimum:1}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!Number.isInteger(input?.page)||input.page<1||input.page>doc.pages.length)throw new Error('Page invalide');goPage(input.page);return {page,playing:false};}}])try{void Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}
